'use strict';

function lastAligned(low, high, step) {
  if (!Number.isSafeInteger(low) || !Number.isSafeInteger(high) ||
      !Number.isSafeInteger(step) || step <= 0) {
    throw new TypeError('arguments must be safe integers and step must be positive');
  }
  if (low > high) return null;

  const remainder = ((high % step) + step) % step;
  const candidate = high - remainder;
  return Number.isSafeInteger(candidate) && candidate >= low ? candidate : null;
}

module.exports = { lastAligned };

