'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['lastAligned']);
assert.strictEqual(typeof api.lastAligned, 'function');

assert.strictEqual(api.lastAligned(1, 10, 3), 9);
assert.strictEqual(api.lastAligned(6, 6, 3), 6);
assert.strictEqual(api.lastAligned(7, 7, 3), null);
assert.strictEqual(api.lastAligned(5, 4, 2), null);
assert.strictEqual(api.lastAligned(1, 2, 3), null);
assert.strictEqual(api.lastAligned(0, 0, 1), 0);
assert.strictEqual(api.lastAligned(-10, -1, 3), -3);
assert.strictEqual(api.lastAligned(-10, 2, 4), 0);
assert.strictEqual(api.lastAligned(-8, -8, 4), -8);
assert.strictEqual(api.lastAligned(-2, -1, 3), null);

const max = Number.MAX_SAFE_INTEGER;
assert.strictEqual(api.lastAligned(max - 2, max, 2), max - 1);
assert.strictEqual(api.lastAligned(max, max, max), max);
assert.strictEqual(api.lastAligned(-max, -max, max), -max);
assert.strictEqual(Number.isSafeInteger(api.lastAligned(max - 2, max, 2)), true);

for (const args of [
  [1.5, 2, 1],
  [1, 2.5, 1],
  [1, 2, 1.5],
  [NaN, 2, 1],
  [1, Infinity, 1],
  [1, 2, 0],
  [1, 2, -1],
  [1, 2, Number.MAX_SAFE_INTEGER + 1],
  ['1', 2, 1],
  [1, null, 1]
]) {
  assert.throws(() => api.lastAligned(...args), TypeError);
}

